#include <iostream>
#include <string>
using namespace std;

int main() {
    string text, pattern;
    cin >> text >> pattern;
    int n = text.size(), m = pattern.size();
    int pos = -1;
    for (int i = 0; i + m <= n; i++) {
        bool match = true;
        for (int j = 0; j < m; j++) {
            if (text[i + j] != pattern[j]) {
                match = false;
                break;
            }
        }
        if (match) { pos = i; break; }
    }
    cout << pos << endl;
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

int main() {
    string s;
    cin >> s;
    int n = s.size();
    s = s + s;
    int i = 0, j = 1, k = 0;
    while (i < n && j < n) {
        if (s[i + k] == s[j + k]) { k++; if (k == n) break; }
        else if (s[i + k] > s[j + k]) { i = i + k + 1; if (i <= j) i = j + 1; k = 0; }
        else { j = j + k + 1; if (j <= i) j = i + 1; k = 0; }
    }
    int ans = min(i, j);
    cout << s.substr(ans, n) << endl;
    return 0;
}

