#include <iostream>
#include <string>
using namespace std;

typedef unsigned long long ull;
const ull base = 131;

ull h[1000005], p[1000005];

ull getHash(int l, int r) {
    return h[r] - h[l - 1] * p[r - l + 1];
}

int main() {
    string s;
    cin >> s;
    int n = s.size();
    s = " " + s;
    p[0] = 1;
    for (int i = 1; i <= n; i++) {
        h[i] = h[i - 1] * base + s[i];
        p[i] = p[i - 1] * base;
    }
    int l1, r1, l2, r2;
    cin >> l1 >> r1 >> l2 >> r2;
    if (getHash(l1, r1) == getHash(l2, r2)) cout << "相同" << endl;
    else cout << "不同" << endl;
    return 0;
}

#include <iostream>
#include <string>
using namespace std;

int ch[1000005][26];
int cnt[1000005];
int tot = 0;

void insert(const string& s) {
    int u = 0;
    for (char c : s) {
        int v = c - 'a';
        if (!ch[u][v]) ch[u][v] = ++tot;
        u = ch[u][v];
    }
    cnt[u]++;
}

bool find(const string& s) {
    int u = 0;
    for (char c : s) {
        int v = c - 'a';
        if (!ch[u][v]) return false;
        u = ch[u][v];
    }
    return cnt[u] > 0;
}

int main() {
    int n;
    cin >> n;
    for (int i = 0; i < n; i++) {
        string op, s;
        cin >> op >> s;
        if (op == "insert") insert(s);
        else cout << (find(s) ? "Yes" : "No") << endl;
    }
    return 0;
}

#include <iostream>
#include <string>
#include <queue>
using namespace std;

int ch[100005][26], cnt[100005], fail[100005], tot = 0;

void insert(const string& s) {
    int u = 0;
    for (char c : s) {
        int v = c - 'a';
        if (!ch[u][v]) ch[u][v] = ++tot;
        u = ch[u][v];
    }
    cnt[u]++;
}

void build() {
    queue<int> q;
    for (int c = 0; c < 26; c++)
        if (ch[0][c]) q.push(ch[0][c]);
    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int c = 0; c < 26; c++) {
            if (ch[u][c]) {
                fail[ch[u][c]] = ch[fail[u]][c];
                q.push(ch[u][c]);
            } else {
                ch[u][c] = ch[fail[u]][c];
            }
        }
    }
}

int main() {
    int n;
    cin >> n;
    for (int i = 0; i < n; i++) { string s; cin >> s; insert(s); }
    build();
    string text;
    cin >> text;
    int u = 0, ans = 0;
    for (char c : text) {
        u = ch[u][c - 'a'];
        for (int v = u; v && cnt[v] != -1; v = fail[v]) {
            ans += cnt[v];
            cnt[v] = -1;
        }
    }
    cout << ans << endl;
    return 0;
}

#include <iostream>
#include <string>
#include <algorithm>
using namespace std;

int n;
string s;
int sa[100005], rk[100005], tmp[100005];

bool cmp(int a, int b) {
    if (rk[a] != rk[b]) return rk[a] < rk[b];
    int ra = a + n/2 < n ? rk[a + n/2] : -1;
    int rb = b + n/2 < n ? rk[b + n/2] : -1;
    return ra < rb;
}

int main() {
    cin >> s;
    n = s.size();
    for (int i = 0; i < n; i++) sa[i] = i;
    for (int i = 0; i < n; i++) rk[i] = s[i];
    for (int k = 1; k < n; k *= 2) {
        sort(sa, sa + n, cmp);
        tmp[sa[0]] = 0;
        for (int i = 1; i < n; i++)
            tmp[sa[i]] = tmp[sa[i-1]] + cmp(sa[i-1], sa[i]);
        for (int i = 0; i < n; i++) rk[i] = tmp[i];
    }
    for (int i = 0; i < n; i++) cout << sa[i] << " ";
    return 0;
}

#include <iostream>
#include <string>
#include <map>
using namespace std;

map<int, int> ch[200005];
int len[200005], link[200005];
int sz, last;

void sam_init() {
    sz = 1; last = 0;
    len[0] = 0; link[0] = -1;
}

void sam_extend(int c) {
    int cur = sz++;
    len[cur] = len[last] + 1;
    int p = last;
    while (p != -1 && !ch[p].count(c)) {
        ch[p][c] = cur;
        p = link[p];
    }
    if (p == -1) link[cur] = 0;
    else {
        int q = ch[p][c];
        if (len[p] + 1 == len[q]) link[cur] = q;
        else {
            int clone = sz++;
            ch[clone] = ch[q];
            len[clone] = len[p] + 1;
            link[clone] = link[q];
            while (p != -1 && ch[p][c] == q) {
                ch[p][c] = clone;
                p = link[p];
            }
            link[q] = link[cur] = clone;
        }
    }
    last = cur;
}

int main() {
    string s;
    cin >> s;
    sam_init();
    for (char c : s) sam_extend(c);
    long long ans = 0;
    for (int i = 1; i < sz; i++) ans += len[i] - len[link[i]];
    cout << ans << endl;
    return 0;
}

#include <iostream>
#include <string>
#include <algorithm>
using namespace std;

int p[200005];

int main() {
    string s;
    cin >> s;
    string t = "#";
    for (char c : s) { t += c; t += "#"; }
    int n = t.size();
    int c = 0, r = 0, maxLen = 0;
    for (int i = 0; i < n; i++) {
        if (i <= r) p[i] = min(r - i, p[2 * c - i]);
        else p[i] = 0;
        while (i - p[i] - 1 >= 0 && i + p[i] + 1 < n && t[i - p[i] - 1] == t[i + p[i] + 1])
            p[i]++;
        if (i + p[i] > r) { c = i; r = i + p[i]; }
        maxLen = max(maxLen, p[i]);
    }
    cout << maxLen << endl;
    return 0;
}
